metrics.workdir_dsl:
workspace "Energy Manager" "C4 model of the home energy management platform" {

    model {
        homeowner = person "Homeowner" "Manages the household's energy use and costs."

        energyManager = softwareSystem "Energy Manager" "Home energy management platform owned and operated by our company." {
            dashboard = container "Dashboard Web App" "Where homeowners see consumption and costs." "Web Application"
            scheduling = container "Scheduling Service" "Plans charging and heating." "Service"
            ratesLibrary = container "Rates Library" "Shared library that computes energy prices from tariff and time of day." "Software Library"
            database = container "Database" "Stores meter readings and schedules." "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Operated by a different organization; provides live meter readings."

        homeowner -> dashboard "Manages household energy use and costs" "Web"
        dashboard -> ratesLibrary "Embeds" "Embedded"
        scheduling -> ratesLibrary "Embeds" "Embedded"
        scheduling -> smartMeterProvider "Fetches live meter readings" "API"
        scheduling -> database "Stores meter readings and schedules" "Database"
    }

    views {
        systemContext energyManager "SystemContext" "System context view of the Energy Manager platform." {
            include homeowner
            include smartMeterProvider
            autolayout
        }

        container energyManager "Containers" "Container view of the Energy Manager platform." {
            include homeowner
            include smartMeterProvider
            include dashboard
            include scheduling
            include ratesLibrary
            include database
            autolayout
        }
    }

    configuration {
        scope "Landscape"
    }
}
